 if ( ! defined( 'ABSPATH' ) ) { exit; } function hvm_text_field_options() { $out = array( '' => '— select —' ); $schemas = array( hvm_fields_schema(), hvm_speaker_schema() ); foreach ( $schemas as $schema ) { foreach ( $schema as $group ) { foreach ( $group['fields'] as $f ) { if ( in_array( $f['type'], array( 'text', 'textarea', 'url', 'number', 'datetime' ), true ) && ! isset( $out[ $f['key'] ] ) ) { $out[ $f['key'] ] = $group['title'] . ' → ' . $f['label']; } } } } return $out; } function hvm_image_field_options() { $out = array( '' => '— select —' ); $schemas = array( hvm_fields_schema(), hvm_speaker_schema() ); foreach ( $schemas as $schema ) { foreach ( $schema as $group ) { foreach ( $group['fields'] as $f ) { if ( 'image' === $f['type'] && ! isset( $out[ $f['key'] ] ) ) { $out[ $f['key'] ] = $group['title'] . ' → ' . $f['label']; } } } } return $out; } function hvm_field_type( $key ) { $flat = hvm_flat_fields( hvm_fields_schema() ); return isset( $flat[ $key ]['type'] ) ? $flat[ $key ]['type'] : 'text'; } function hvm_format_datetime( $value, $preset = '', $custom = '' ) { $value = trim( (string) $value ); if ( '' === $value ) { return ''; } $dt = date_create( str_replace( 'T', ' ', $value ) ); if ( ! $dt ) { return $value; } if ( '' === $preset ) { return $dt->format( 'M' ) . ' ' . $dt->format( 'j' ) . '<sup>' . $dt->format( 'S' ) . '</sup> ' . $dt->format( 'Y' ); } switch ( $preset ) { case 'date': $fmt = 'F j, Y'; break; case 'datetime': $fmt = 'F j, Y \a\t g:i a'; break; case 'time': $fmt = 'g:i a'; break; case 'year': $fmt = 'Y'; break; case 'custom': $fmt = '' !== $custom ? $custom : 'M jS Y'; break; default: $fmt = 'M jS Y'; } return $dt->format( $fmt ); } function hvm_format_date_range( $start, $end = '' ) { $start = trim( (string) $start ); if ( '' === $start ) { return ''; } $s = date_create( str_replace( 'T', ' ', $start ) ); if ( ! $s ) { return $start; } $end = trim( (string) $end ); $e = '' !== $end ? date_create( str_replace( 'T', ' ', $end ) ) : null; if ( ! $e || $e->format( 'Y-m-d' ) === $s->format( 'Y-m-d' ) ) { return $s->format( 'F j, Y' ); } if ( $s->format( 'Y' ) === $e->format( 'Y' ) ) { if ( $s->format( 'm' ) === $e->format( 'm' ) ) { return $s->format( 'F j' ) . '–' . $e->format( 'j' ) . ', ' . $s->format( 'Y' ); } return $s->format( 'F j' ) . ' – ' . $e->format( 'F j' ) . ', ' . $s->format( 'Y' ); } return $s->format( 'F j, Y' ) . ' – ' . $e->format( 'F j, Y' ); } function hvm_format_datetime_time_range( $start, $end = '' ) { $start = trim( (string) $start ); if ( '' === $start ) { return ''; } $s = date_create( str_replace( 'T', ' ', $start ) ); if ( ! $s ) { return ''; } $st = $s->format( 'H:i' ); $end = trim( (string) $end ); if ( '' === $end ) { return $st; } $e = date_create( str_replace( 'T', ' ', $end ) ); if ( ! $e ) { return $st; } return $st . ' → ' . $e->format( 'H:i' ); } function hvm_format_time_range( $start, $end = '' ) { $start = trim( (string) $start ); $end = trim( (string) $end ); if ( '' === $start && '' === $end ) { return ''; } if ( '' === $end ) { return $start; } if ( '' === $start ) { return $end; } return $start . ' → ' . $end; } function hvm_event_type_options() { $out = array(); foreach ( array_keys( hvm_managed_cpts() ) as $pt ) { $o = get_post_type_object( $pt ); $out[ $pt ] = $o ? $o->labels->singular_name : ucfirst( $pt ); } return $out; } function hvm_latest_event_url( $post_type = 'mixer', $order = 'recent' ) { if ( ! array_key_exists( $post_type, hvm_managed_cpts() ) ) { $post_type = 'mixer'; } $base = array( 'post_type' => $post_type, 'post_status' => 'publish', 'posts_per_page' => 1, 'no_found_rows' => true, 'fields' => 'ids', ); if ( 'upcoming' === $order ) { $now = date_i18n( 'Y-m-d\TH:i' ); $mk = hvm_meta_key( 'event_date' ); $ids = get_posts( array_merge( $base, array( 'meta_key' => $mk, 'orderby' => 'meta_value', 'order' => 'ASC', 'meta_query' => array( array( 'key' => $mk, 'value' => $now, 'compare' => '>=', 'type' => 'CHAR', ) ), ) ) ); if ( $ids )